  // RB-04: Componentry Cursor-Repel Particle Typography Canvas
  const pCanvas = document.getElementById("particleTextCanvas");
  if (pCanvas && pCanvas.getContext) {
    const ctx = pCanvas.getContext("2d");
    const particles = [];
    const cols = 28;
    const rows = 9;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const ox = 24 + c * 10.5;
        const oy = 32 + r * 13;
        particles.push({
          ox,
          oy,
          x: ox,
          y: oy,
          vx: 0,
          vy: 0,
          color: (r + c) % 3 === 0 ? "#38d6ff" : (r + c) % 2 === 0 ? "#ff9d2e" : "#a8ff35"
        });
      }
    }
    let mx = -999;
    let my = -999;
    pCanvas.addEventListener("pointermove", (e) => {
      const rect = pCanvas.getBoundingClientRect();
      mx = ((e.clientX - rect.left) / rect.width) * pCanvas.width;
      my = ((e.clientY - rect.top) / rect.height) * pCanvas.height;
    });
    pCanvas.addEventListener("pointerleave", () => {
      mx = -999;
      my = -999;
    });
    function stepParticles() {
      ctx.clearRect(0, 0, pCanvas.width, pCanvas.height);
      ctx.fillStyle = "rgba(255,255,255,0.12)";
      ctx.font = "800 13px Plus Jakarta Sans, sans-serif";
      ctx.fillText("RED BANANA PARTICLE FIELD • MOVE CURSOR", 24, 154);
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        const dx = p.x - mx;
        const dy = p.y - my;
        const dist = Math.hypot(dx, dy);
        if (dist < 52 && dist > 0.1) {
          const force = (52 - dist) / 52;
          p.vx += (dx / dist) * force * 3.4;
          p.vy += (dy / dist) * force * 3.4;
        }
        p.vx += (p.ox - p.x) * 0.12;
        p.vy += (p.oy - p.y) * 0.12;
        p.vx *= 0.82;
        p.vy *= 0.82;
        p.x += p.vx;
        p.y += p.vy;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2.3, 0, Math.PI * 2);
        ctx.fill();
      }
      requestAnimationFrame(stepParticles);
    }
    requestAnimationFrame(stepParticles);
  }

